  app.post("/api/validation/batch", requireAuth, async (req: Request, res: Response) => {
    try {
      const { resources, options } = req.body as any;
      
      if (!Array.isArray(resources) || resources.length === 0) {
        return res.status(400).json({ error: "Array of FHIR resources required" });
      }
      
      const results = await Promise.all(
        resources.map((resource: FhirResource) => 
          validationEngine.validateResource(resource, options)
        )
      );
      
      const summary = {
        totalResources: resources.length,
        validCount: results.filter(r => r.isValid).length,
        invalidCount: results.filter(r => !r.isValid).length,
        results,
      };
      
      auditLog(req, "fhir_batch_validation", "mixed", undefined, {
        totalResources: resources.length,
        validCount: summary.validCount,
      });
      
      res.json(summary);
    } catch (error) {
      console.error("Batch validation error:", error);
      res.status(500).json({ error: "Failed to validate resources" });
    }
  });


