  // Complete a milestone

  app.post("/api/health-journeys/:journeyId/milestones/:milestoneId/complete", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const journey = await storage.getHealthJourney((req.params as any).journeyId);
      if (!journey) {
        return res.status(404).json({ error: "Journey not found" });
      }
      if (journey.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      // Verify the milestone actually belongs to this journey before mutating
      const milestoneCheck = await storage.getJourneyMilestone((req.params as any).milestoneId);
      if (!milestoneCheck || milestoneCheck.journeyId !== (req.params as any).journeyId) {
        return res.status(403).json({ error: "Access denied" });
      }
      const milestone = await storage.updateJourneyMilestone((req.params as any).milestoneId, {
        status: "completed",
        completedAt: new Date(),
      });
      
      // Award points
      if (milestone?.pointsReward) {
        await storage.awardPoints(userId, milestone.pointsReward, "milestone_completed", "milestones", "journey_milestone", milestone.id);
      }
      
      // Unlock next milestone
      const milestones = await storage.getJourneyMilestones((req.params as any).journeyId);
      const currentIndex = milestones.findIndex((m: any) => m.id === (req.params as any).milestoneId);
      if (currentIndex >= 0 && currentIndex < milestones.length - 1) {
        await storage.updateJourneyMilestone(milestones[currentIndex + 1].id, {
          status: "available",
          unlockedAt: new Date(),
        });
      }
      
      // Update journey progress
      const completedCount = milestones.filter((m: any) => m.status === "completed").length + 1;
      const progress = Math.round((completedCount / milestones.length) * 100);
      await storage.updateHealthJourney((req.params as any).journeyId, {
        progressPercentage: progress,
        ...(progress === 100 ? { status: "completed", completedAt: new Date() } : {}),
      });
      
      res.json(milestone);
    } catch (error) {
      console.error("Complete milestone error:", error);
      res.status(500).json({ error: "Failed to complete milestone" });
    }
  });

