  app.get("/api/sms/log", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const userLog = smsLog.filter(entry => entry.userId === userId);
      userLog.sort((a, b) => new Date(b.sentAt).getTime() - new Date(a.sentAt).getTime());
      res.json(userLog);
    } catch (error) {
      console.error("Get SMS log error:", error);
      res.status(500).json({ error: "Failed to get SMS log" });
    }
  });


  app.post("/api/sms/log", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { recipientPhone, recipientName, messagePreview, status } = req.body as any;

      const entry = {
        id: `sms-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        userId,
        recipientPhone,
        recipientName: recipientName || "Unknown",
        messagePreview: messagePreview || "",
        status: status || "sent",
        sentAt: new Date().toISOString(),
      };

      smsLog.push(entry);
      res.status(201).json(entry);
    } catch (error) {
      console.error("Log SMS error:", error);
      res.status(500).json({ error: "Failed to log SMS" });
    }
  });

  // ==================== TWILIO SMS SENDING ====================


  app.post("/api/sms/send", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { to, message } = req.body as any;

      if (!to || !message) {
        return res.status(400).json({ error: "Phone number and message are required" });
      }

      if (!checkSmsSendRateLimit(userId)) {
        return res.status(429).json({ error: "SMS send limit reached. Please try again later." });
      }

      const result = await twilioSmsService.sendSms(to, message);

      const entry = {
        id: `sms-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        userId,
        recipientPhone: to,
        recipientName: "Direct",
        messagePreview: message.substring(0, 100),
        status: result.success ? "sent" : "error",
        sentAt: new Date().toISOString(),
        twilioSid: result.sid || null,
      };
      smsLog.push(entry);

      if (result.success) {
        res.json({ success: true, sid: result.sid });
      } else {
        res.status(500).json({ success: false, error: result.error });
      }
    } catch (error) {
      console.error("Send SMS error:", error);
      res.status(500).json({ error: "Failed to send SMS" });
    }
  });

